# Maybe something related to n-th prime
import math

def prime(n):
    if n == 1: return 2
    ns = []
    is_prime = [True] * (n*10 + 100)  # estimate
    is_prime[0] = is_prime[1] = False
    for i in range(2, int((n*10+100)**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, len(is_prime), i):
                is_prime[j] = False
    for x in is_prime[:n*10+100]:
        if x: ns.append(x)
    return ns[0]

primes = [prime(i) for i in range(1, 11)]
print("First 10 primes:", primes)
for m in [2, 3, 4, 5, 6, 7, 8, 9, 10]:
    mod_seq = [p % m for p in primes]
    print(f"Primes mod {m}: {mod_seq}")

